package com.aggrotag;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Keybind;

@ConfigGroup("aggrotag")
public interface AggroTagConfig extends Config {

    // ── TOP LEVEL ITEMS (NO SECTION) ───────────────────────────────────────────

    @ConfigItem(keyName = "aggroNameColor", name = "Aggro Tag Color", description = "Color of the name tag for NPCs that would attack you on approach.", position = 1)
    default Color aggroNameColor() {
        return new Color(255, 60, 60, 230);
    }

    @ConfigItem(keyName = "targetingNameColor", name = "Targeting-You Color", description = "<html>Color of the name tag when an NPC is actively targeting/chasing you right now.<br>Lets you distinguish 'will attack' from 'already chasing'.</html>", position = 2)
    default Color targetingNameColor() {
        return new Color(255, 140, 0, 255);
    }

    @ConfigItem(keyName = "hideAggro", name = "Hide Aggro Tag", description = "<html>When enabled, hides the aggro name tag (or square marker) <br>for NPCs that are aggressive but not currently targeting you. <br>Max hit and other overlays are unaffected.</html>", position = 3)
    default boolean hideAggro() {
        return false;
    }

    @ConfigItem(keyName = "hideTargeting", name = "Hide Targeting-You Tag", description = "<html>When enabled, hides the targeting-you name tag (or square marker) <br>for NPCs that are actively targeting/chasing you. <br>Max hit and other overlays are unaffected.</html>", position = 4)
    default boolean hideTargeting() {
        return false;
    }

    @ConfigItem(keyName = "preventTagOverlap", name = "Prevent Tag Overlap", description = "When enabled, NPC tags will physically bump into each other and float apart so they don't overlap.", position = 5)
    default boolean preventTagOverlap() {
        return true;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "baseOpacity", name = "Base Tag Opacity %", description = "General opacity for all active tags. 0 = fully invisible, 100 = full brightness. Default 100.", position = 6)
    default int baseOpacity() {
        return 100;
    }

    @Range(min = -500, max = 500)
    @ConfigItem(keyName = "tagVerticalOffset", name = "Vertical Position Shift", description = "Shift the entire tag layout up (negative) or down (positive) on your screen.", position = 7)
    default int tagVerticalOffset() {
        return 0;
    }

    @Range(min = -500, max = 500)
    @ConfigItem(keyName = "tagHorizontalOffset", name = "Horizontal Position Shift", description = "Shift the entire tag layout left (negative) or right (positive) on your screen.", position = 8)
    default int tagHorizontalOffset() {
        return 0;
    }

    @ConfigItem(keyName = "dimInSingleCombat", name = "Dim Others in Single Combat", description = "<html>In single-combat zones, when you are already fighting an NPC,<br>all other aggressive NPC tags are dimmed — they cannot attack you<br>while your combat slot is occupied. Tags return to full brightness<br>the moment your target dies. Has no effect in multi-combat areas.</html>", position = 9)
    default boolean dimInSingleCombat() {
        return true;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "dimmedOpacity", name = "Dim In-Combat Tags %", description = "<html>How transparent dimmed (when engaged in single combat) NPC tags appear. <br>0 = fully invisible, 100 = full brightness. Default 25.</html>", position = 10)
    default int dimmedOpacity() {
        return 25;
    }

    @ConfigItem(keyName = "slayerWarnings", name = "Slayer Warnings!", description = "<html>Shows missing slayer equipment icons with a <b><font color='#ff361fff'>RED</font></b> cancel sign<br>on tagged slayer monsters when you are on-task but not wearing<br>the required protection (e.g., Earmuffs for Banshees).</html>", position = 11)
    default boolean slayerWarnings() {
        return true;
    }

    @ConfigItem(keyName = "onlyTagSlayer", name = "Only Tag Slayer", description = "When enabled, ONLY NPCs that are your current Slayer task will be tagged.<br>All other NPCs will be ignored by the plugin.", position = 12)
    default boolean onlyTagSlayer() {
        return false;
    }

    @ConfigItem(keyName = "onlyTagBosses", name = "Only Tag Bosses", description = "When enabled, ONLY bosses will be tagged.<br>All other NPCs will be ignored by the plugin.", position = 13)
    default boolean onlyTagBosses() {
        return false;
    }

    @Range(min = 0, max = 2000)
    @ConfigItem(keyName = "excludeNpcsAboveLevel", name = "Exclude NPCs > Lvl", description = "Ignore NPCs with a combat level greater than this value. Set to 0 to disable.", position = 14)
    default int excludeNpcsAboveLevel() {
        return 0;
    }

    @Range(min = 0, max = 2000)
    @ConfigItem(keyName = "excludeNpcsBelowLevel", name = "Exclude NPCs < Lvl", description = "Ignore NPCs with a combat level lower than this value, including NPCs without a combat level. Set to 0 to disable.", position = 15)
    default int excludeNpcsBelowLevel() {
        return 0;
    }

    @Range(min = 0, max = 500)
    @ConfigItem(keyName = "excludeNpcsAboveMaxHit", name = "Exclude NPCs > Max Hit", description = "Ignore NPCs whose max hit is greater than this value. Set to 0 to disable.", position = 16)
    default int excludeNpcsAboveMaxHit() {
        return 0;
    }

    @Range(min = 0, max = 500)
    @ConfigItem(keyName = "excludeNpcsBelowMaxHit", name = "Exclude NPCs < Max Hit", description = "<html>Ignore NPCs whose max hit is lower than this value, including NPCs whose max hit<br>is not in the bundled wiki dataset. Set to 0 to disable.</html>", position = 17)
    default int excludeNpcsBelowMaxHit() {
        return 0;
    }

    // ── SECTIONS ───────────────────────────────────────────────────────────────

    @ConfigSection(name = "Max Hit", description = "Settings for displaying NPC max hits", position = 18, closedByDefault = true)
    String maxHitSection = "maxHitSection";

    @ConfigSection(name = "Square Marker", description = "Replace NPC names with a customizable square marker", position = 20, closedByDefault = true)
    String squareMarkerSection = "squareMarkerSection";

    @ConfigSection(name = "Aggression Radius", description = "Settings for visualizing the attack range of aggressive NPCs", position = 30, closedByDefault = true)
    String radiusSection = "radiusSection";

    @ConfigSection(name = "NPC Outline", description = "Settings for drawing an outline around aggressive NPCs", position = 25, closedByDefault = true)
    String npcOutlineSection = "npcOutlineSection";

    @ConfigSection(name = "NPC ID & Level", description = "Options for showing NPC IDs and Combat Levels on tags", position = 50, closedByDefault = true)
    String npcIdSection = "npcIdSection";

    @ConfigSection(name = "Edge Cases", description = "Toggle tracking of specific situational aggression rules", position = 40, closedByDefault = true)
    String edgeCasesSection = "edgeCasesSection";

    // ── MAX HIT ────────────────────────────────────────────────────────────────

    @ConfigItem(keyName = "showAggroMaxHit", name = "Show Aggro Max Hit", description = "Displays the NPC's max hit for aggressive NPCs that are not currently targeting you.", position = 1, section = maxHitSection)
    default boolean showAggroMaxHit() {
        return true;
    }

    @ConfigItem(keyName = "showTargetingMaxHit", name = "Show Targeting-You Max Hit", description = "Displays the NPC's max hit for NPCs that are actively targeting/chasing you.", position = 2, section = maxHitSection)
    default boolean showTargetingMaxHit() {
        return true;
    }

    @ConfigItem(keyName = "showAllMaxHits", name = "Show All Max Hits", description = "Displays the max hit for ALL NPCs, including passive ones.", position = 3, section = maxHitSection)
    default boolean showAllMaxHits() {
        return false;
    }

    @ConfigItem(keyName = "maxHitBaseColor", name = "Max Hit Color", description = "The color of the max hit number. Ignored while 'Color Max Hit by Attack Style' is enabled.", position = 4, section = maxHitSection)
    default Color maxHitBaseColor() {
        return Color.WHITE;
    }

    @ConfigItem(keyName = "colorByAttackStyle", name = "Color Max Hit by Attack Style", description = "<html>When enabled, overwrites the Max Hit Color with a separate colored number per attack style:<br>&nbsp;&nbsp;<b><font color='#ffe550ff'>Yellow</font></b> = Melee &nbsp;<b><font color='#3CFF64'>Green</font></b> = Ranged &nbsp;<b><font color='#6496FF'>Blue</font></b> = Magic<br>Falls back to the Max Hit Color if the attack style is unknown.</html>", position = 5, section = maxHitSection)
    default boolean colorByAttackStyle() {
        return true;
    }

    @ConfigItem(keyName = "showHpPercent", name = "Show Max Hit as % of HP", description = "<html>Appends the max hit as a percentage of your current Hitpoints, e.g. [15 \u00b7 25%]. <br>Values over 100% mean the NPC can theoretically one-shot you.</html>", position = 6, section = maxHitSection)
    default boolean showHpPercent() {
        return false;
    }

    @Range(min = 0, max = 5)
    @ConfigItem(keyName = "hpPercentSizeIncrease", name = "Base HP % Size Increase", description = "Increase the font size of the % number.", position = 7, section = maxHitSection)
    default int hpPercentSizeIncrease() {
        return 0;
    }

    @ConfigItem(keyName = "colorHpNumber", name = "Custom HP # Colors", description = "<html>When enabled, overrides both the Max Hit Color and the 'Color Max Hit by Attack Style' coloring<br>and instead colors the max hit number using your threshold colors below.<br>Requires thresholds to be configured.</html>", position = 8, section = maxHitSection)
    default boolean colorHpNumber() {
        return true;
    }

    @ConfigItem(keyName = "colorHpPercent", name = "Custom HP % Colors", description = "Color the % text based on danger level.", position = 9, section = maxHitSection)
    default boolean colorHpPercent() {
        return true;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "hpPercentThreshold1", name = "HP % Threshold 1", description = "First threshold for HP percentage coloring (e.g. 50).", position = 10, section = maxHitSection)
    default int hpPercentThreshold1() {
        return 50;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "hpPercentThreshold2", name = "HP % Threshold 2", description = "Second threshold for HP percentage coloring (e.g. 100).", position = 11, section = maxHitSection)
    default int hpPercentThreshold2() {
        return 100;
    }

    @ConfigItem(keyName = "colorHpPercent50", name = "Threshold 1 Color", description = "Color when the max hit is > Threshold 1 of your current HP.", position = 12, section = maxHitSection)
    default Color colorHpPercent50() {
        return new Color(39, 232, 163);
    }

    @ConfigItem(keyName = "colorHpPercent100", name = "Threshold 2 Color", description = "Color when the max hit is > Threshold 2 of your current HP.", position = 13, section = maxHitSection)
    default Color colorHpPercent100() {
        return new Color(240, 25, 195);
    }

    @Range(min = 0, max = 10)
    @ConfigItem(keyName = "hpPercentSizeIncrease50", name = "Threshold 1 Size Increase", description = "Additional font size increase when max hit is > Threshold 1.", position = 14, section = maxHitSection)
    default int hpPercentSizeIncrease50() {
        return 4;
    }

    @Range(min = 0, max = 10)
    @ConfigItem(keyName = "hpPercentSizeIncrease100", name = "Threshold 2 Size Increase", description = "Additional font size increase when max hit is > Threshold 2.", position = 15, section = maxHitSection)
    default int hpPercentSizeIncrease100() {
        return 9;
    }

    // ── SQUARE MARKER ──────────────────────────────────────────────────────────

    @ConfigItem(keyName = "useSquareMarker", name = "Use Square Marker", description = "Replace the NPC name text with a simple square marker.", position = 1, section = squareMarkerSection)
    default boolean useSquareMarker() {
        return false;
    }

    @ConfigItem(keyName = "squareMarkerColor", name = "Square Color", description = "The inner fill color of the square marker.", position = 2, section = squareMarkerSection)
    default Color squareMarkerColor() {
        return new Color(255, 60, 60, 230);
    }

    @ConfigItem(keyName = "squareMarkerTargetColor", name = "Targeting-You Color", description = "The inner fill color of the square marker when the NPC is targeting you.", position = 3, section = squareMarkerSection)
    default Color squareMarkerTargetColor() {
        return new Color(255, 140, 0, 255);
    }

    @ConfigItem(keyName = "squareOutlineColor", name = "Outline Color", description = "The border outline color of the square marker.", position = 4, section = squareMarkerSection)
    default Color squareOutlineColor() {
        return Color.BLACK;
    }

    @Range(min = 1, max = 50)
    @ConfigItem(keyName = "squareSize", name = "Square Size", description = "The width and height of the square marker.", position = 5, section = squareMarkerSection)
    default int squareSize() {
        return 4;
    }

    @Range(min = 0, max = 10)
    @ConfigItem(keyName = "squareOutlineSize", name = "Outline Thickness", description = "The thickness of the square's outline.", position = 6, section = squareMarkerSection)
    default int squareOutlineSize() {
        return 0;
    }

    // ── NPC OUTLINE ────────────────────────────────────────────────────────────

    @ConfigItem(keyName = "npcOutlineAggressive", name = "Outline Aggressive NPCs", description = "Draw an outline around aggressive NPCs that are not currently targeting you.", position = 1, section = npcOutlineSection)
    default boolean npcOutlineAggressive() {
        return true;
    }

    @ConfigItem(keyName = "npcOutlineTargeting", name = "Outline Targeting-You NPCs", description = "Draw an outline around NPCs that are actively targeting/chasing you.", position = 2, section = npcOutlineSection)
    default boolean npcOutlineTargeting() {
        return true;
    }

    @ConfigItem(keyName = "npcOutlineAggroColor", name = "Outline Aggro Color", description = "Color of the outline for NPCs that would attack you on approach.", position = 3, section = npcOutlineSection)
    default Color npcOutlineAggroColor() {
        return new Color(255, 60, 60, 230);
    }

    @ConfigItem(keyName = "npcOutlineTargetingYouColor", name = "Outline Targeting-You Color", description = "Color of the outline when an NPC is actively targeting/chasing you right now.", position = 4, section = npcOutlineSection)
    default Color npcOutlineTargetingYouColor() {
        return new Color(255, 140, 0, 255);
    }

    @Range(min = 1, max = 50)
    @ConfigItem(keyName = "npcOutlineWidth", name = "Outline Width", description = "Width of the NPC outline.", position = 5, section = npcOutlineSection)
    default int npcOutlineWidth() {
        return 1;
    }

    @Range(min = 0, max = 50)
    @ConfigItem(keyName = "npcOutlineFeather", name = "Outline Feather", description = "How much to feather/blur the NPC outline.", position = 6, section = npcOutlineSection)
    default int npcOutlineFeather() {
        return 3;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "npcOutlineOpacity", name = "Outline Opacity", description = "Adjust the opacity of the NPC outline (0 is fully transparent, 100 is fully opaque).", position = 7, section = npcOutlineSection)
    default int npcOutlineOpacity() {
        return 100;
    }

    // ── AGGRESSION RADIUS ──────────────────────────────────────────────────────

    @ConfigItem(keyName = "disableAggroRadius", name = "Disable Aggression Radius", description = "When enabled, disables the overlay display of the aggression radius entirely.", position = 0, section = radiusSection)
    default boolean disableAggroRadius() {
        return false;
    }

    @ConfigItem(keyName = "radiusHotkey", name = "Show All Hotkey", description = "Press and hold this key to show the aggression radius of all aggressive NPCs.", position = 1, section = radiusSection)
    default Keybind radiusHotkey() {
        return Keybind.CTRL;
    }

    @ConfigItem(keyName = "radiusToggle", name = "Toggle (Instead of Hold)", description = "When enabled, pressing the hotkey toggles the radius on and off rather than requiring you to hold it.", position = 2, section = radiusSection)
    default boolean radiusToggle() {
        return true;
    }

    @ConfigItem(keyName = "hoverRadius", name = "Show on Mouse Hover", description = "Show the aggression radius when you hover your mouse over an aggressive NPC.", position = 3, section = radiusSection)
    default boolean hoverRadius() {
        return false;
    }

    @ConfigItem(keyName = "autoRadius", name = "Check For NPC Radius Automatically", description = "<html>When enabled, the plugin uses hard-coded NPC aggression ranges<br>sourced from the OSRS Wiki (e.g. Kurask 2-tile, DKs 7-tile, etc.).<br>NPCs without a hard-coded range default to 5 tiles.<br><br>When disabled, every NPC uses the manual Aggression Radius slider below.</html>", position = 4, section = radiusSection)
    default boolean autoRadius() {
        return true;
    }

    @Range(min = 1, max = 15)
    @ConfigItem(keyName = "defaultRadius", name = "Override Radius (Tiles)", description = "The size of the radius. Only used when 'Check For NPC Radius Automatically' is disabled.", position = 5, section = radiusSection)
    default int defaultRadius() {
        return 5;
    }

    @ConfigItem(keyName = "radiusColor", name = "Radius Color", description = "The color of the aggression radius overlay.", position = 6, section = radiusSection)
    default Color radiusColor() {
        return new Color(124, 12, 12);
    }

    @ConfigItem(keyName = "radiusColorByAttackStyle", name = "Color by Attack Style", description = "When enabled, overwrites the radius color with the color of the attack style (melee=yellow, ranged=green, magic=blue).", position = 7, section = radiusSection)
    default boolean radiusColorByAttackStyle() {
        return false;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "radiusOpacity", name = "Radius Opacity", description = "Adjust the opacity of the aggression radius (0 is fully transparent, 100 is fully opaque).", position = 8, section = radiusSection)
    default int radiusOpacity() {
        return 8;
    }

    @ConfigItem(keyName = "dimRadiusInCombat", name = "Dim Radius While in Combat", description = "<html>When enabled, the aggression radius fades to near-invisible<br>while you are actively in combat, then returns to full opacity<br>when combat ends. Reduces visual clutter during fights.</html>", position = 9, section = radiusSection)
    default boolean dimRadiusInCombat() {
        return true;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(keyName = "dimmedRadiusOpacity", name = "Dimmed Radius Opacity %", description = "The opacity the aggression radius fades to while in combat (0 = invisible, 100 = full). Only used when 'Dim Radius While in Combat' is enabled.", position = 10, section = radiusSection)
    default int dimmedRadiusOpacity() {
        return 4;
    }

    @ConfigItem(keyName = "radiusLineOfSight", name = "Line of Sight (LOS) Radius", description = "<html>Dynamically shapes the radius to only show tiles the NPC can actually see,<br>blocking it behind walls/objects.<br><br><b><font color='#ff361fff'>Warning:</font></b> Checking LOS tile-by-tile can impact FPS if many NPCs are on screen.</html>", position = 11, section = radiusSection)
    default boolean radiusLineOfSight() {
        return true;
    }

    @ConfigItem(keyName = "radiusTrueTile", name = "Snap to True Tile", description = "<html>Snaps the aggression radius to the server's strict grid (True Tile) <br>rather than gliding smoothly with the NPC's animation.</html>", position = 12, section = radiusSection)
    default boolean radiusTrueTile() {
        return true;
    }

    @ConfigItem(keyName = "highlightSouthwestTile", name = "Highlight Southwest Tile", description = "Highlights the Southwest tile of the NPC, which is the tile used to calculate its aggression.", position = 13, section = radiusSection)
    default boolean highlightSouthwestTile() {
        return false;
    }

    @ConfigItem(keyName = "southwestTileColor", name = "Southwest Tile Color", description = "The color used to highlight the Southwest tile of the NPC.", position = 14, section = radiusSection)
    default Color southwestTileColor() {
        return new Color(94, 216, 168, 255);
    }

    // ── NPC ID & LEVEL
    // ─────────────────────────────────────────────────────────────

    @ConfigItem(keyName = "showNpcLevel", name = "Show NPC Level", description = "Appends the NPC Combat Level to the left of the tagged NPC name.", position = 0, section = npcIdSection)
    default boolean showNpcLevel() {
        return false;
    }

    @ConfigItem(keyName = "showNpcId", name = "Show Tagged NPC ID", description = "Appends the NPC ID to the left of the tagged NPC name.", position = 1, section = npcIdSection)
    default boolean showNpcId() {
        return false;
    }

    @ConfigItem(keyName = "alwaysShowNpcId", name = "Show Untagged NPC ID", description = "Shows the NPC ID for all untagged NPCs.", position = 2, section = npcIdSection)
    default boolean alwaysShowNpcId() {
        return false;
    }

    @ConfigItem(keyName = "npcDataVersion", name = "NPC Data Version", description = "The date npc_data.json was last rebuilt from the OSRS Wiki for aggression and max-hit data.", position = 3, section = npcIdSection)
    default String npcDataVersion() {
        return "2026-08-20";
    }

    // ── EDGE CASES ─────────────────────────────────────────────────────────────

    @ConfigItem(keyName = "trackTolerance", name = "Track 10-Minute Tolerance", description = "Automatically hides aggression tags after you've been in the same area for 10 minutes. Resets when you run out of the tolerance zone.", position = 1, section = edgeCasesSection)
    default boolean trackTolerance() {
        return true;
    }

    @ConfigItem(keyName = "slayerTaskIntegration", name = "Slayer Task Integration", description = "Dynamically tags task-only aggressors (e.g. Kurasks, Wyverns, Wyrms) when you are on their Slayer task. Makes them passive when off-task.", position = 2, section = edgeCasesSection)
    default boolean slayerTaskIntegration() {
        return true;
    }

    @ConfigItem(keyName = "minigameBehavior", name = "Minigames", description = "<html>Controls the plugin inside raids and combat minigames where standard aggression rules don't apply (or visual clutter is high):<br>&nbsp;&nbsp;<b>Fight Caves</b>, <b>Inferno</b>, <b>Colosseum</b>, <b>NMZ</b><br>&nbsp;&nbsp;<b>The Gauntlet & Corrupted Gauntlet</b><br>&nbsp;&nbsp;<b>Chambers of Xeric</b>, <b>Theatre of Blood</b>, <b>ToA</b><br>&nbsp;&nbsp;<b>Pest Control</b>, <b>Barbarian Assault</b>, <b>Soul Wars</b>, <b>Temple Trekking</b>, <b>GOTR</b><br><br><b>Show Everything</b> \u2014 legacy, all tags visible<br><b>Hide Names, Show Max Hits</b> \u2014 (default) clears the clutter, keeps combat data<br><b>Disable Plugin Completely</b> \u2014 hides everything inside these zones</html>", position = 3, section = edgeCasesSection)
    default MinigameBehavior minigameBehavior() {
        return MinigameBehavior.DISABLE_ENTIRELY;
    }

    @ConfigItem(keyName = "trackGwd", name = "God Wars Dungeon", description = "God items prevent aggression from matching factions.", position = 4, section = edgeCasesSection)
    default boolean trackGwd() {
        return true;
    }

    @ConfigItem(keyName = "trackApeAtoll", name = "Ape Atoll Monkeys", description = "Monkey Greegrees prevent aggression on Ape Atoll.", position = 5, section = edgeCasesSection)
    default boolean trackApeAtoll() {
        return true;
    }

    @ConfigItem(keyName = "trackDesertBandits", name = "Desert Bandits", description = "Saradomin/Zamorak items trigger aggression in the Bandit Camp.", position = 6, section = edgeCasesSection)
    default boolean trackDesertBandits() {
        return true;
    }

    @ConfigItem(keyName = "trackVyrewatch", name = "Darkmeyer Vyres", description = "Vyre noble clothing prevents aggression from Vyres.", position = 7, section = edgeCasesSection)
    default boolean trackVyrewatch() {
        return true;
    }

    @ConfigItem(keyName = "trackRevenants", name = "Wilderness Revenants", description = "A charged Bracelet of Ethereum prevents aggression from Revenants.", position = 8, section = edgeCasesSection)
    default boolean trackRevenants() {
        return true;
    }

    @ConfigItem(keyName = "trackMourners", name = "Mourner Headquarters", description = "Full Mourner gear prevents aggression from Mourners.", position = 9, section = edgeCasesSection)
    default boolean trackMourners() {
        return true;
    }

    @ConfigItem(keyName = "trackBosses", name = "Bosses", description = "Tag boss NPCs with aggression info", position = 10, section = edgeCasesSection)
    default boolean trackBosses() { return false; }

    @ConfigItem(keyName = "trackGoadingPotion", name = "Goading Potion", description = "<html>Displays a 9x9 (4-tile) aggro radius on all attackable NPCs when under the effect of a Goading Potion.<br>Automatically syncs with the game's chat messages.</html>", position = 11, section = edgeCasesSection)
    default boolean trackGoadingPotion() {
        return true;
    }

}

package com.aggrotag;

import javax.inject.Inject;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.awt.Polygon;
import java.awt.BasicStroke;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.RenderingHints;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;

import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.api.Client;
import javax.annotation.Nonnull;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.Text;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.coords.LocalPoint;

/**
 * Renders name tags (and optional max hit labels) above aggressive NPCs.
 *
 * <h3>Name tag colours</h3>
 * <ul>
 * <li>Configurable red (default) — NPC is aggressive but not currently
 * targeting you.</li>
 * <li>Configurable orange (default) — NPC is <em>actively
 * chasing/targeting</em> you right now.</li>
 * </ul>
 *
 * <h3>Max hit display modes</h3>
 * <ul>
 * <li><b>Show Max Hit OFF</b> — no max hit shown.</li>
 * <li><b>ON, Color by Style OFF</b> — single {@code [N]} in the configured
 * Max Hit Color (white by default).</li>
 * <li><b>ON, Color by Style ON</b> — one label per attack style:
 * <span style="color:gold">Yellow</span> melee,
 * <span style="color:#6496FF">Blue</span> magic,
 * <span style="color:green">Green</span> ranged.
 * Falls back to the Max Hit Color when the style is unknown.</li>
 * <li><b>Show HP % ON</b> — appends {@code · N%} (of current HP) after the
 * number(s).
 * Values over 100% mean the NPC can theoretically one-shot you.</li>
 * </ul>
 *
 * <p>The top-level {@code Exclude NPCs > Max Hit} / {@code Exclude NPCs < Max Hit}
 * filters drop a whole NPC from this overlay before anything is drawn, the same
 * way the combat level filters do.</p>
 */
public class AggroTagOverlay extends Overlay {
    // ── Max hit colours ───────────────────────────────────────────────────────

    /** Yellow — melee attack style. */
    private static final Color COLOR_MELEE = new Color(255, 210, 0, 255);
    /** Blue — magic attack style. */
    private static final Color COLOR_MAGIC = new Color(100, 160, 255, 255);
    /** Green — ranged attack style. */
    private static final Color COLOR_RANGED = new Color(60, 220, 60, 255);
    /** Grey — HP percentage suffix (neutral, doesn't clash with style colours). */
    private static final Color COLOR_PCT = new Color(210, 210, 210, 220);
    /** Drop shadow for all text. */
    private static final Color COLOR_SHADOW = new Color(0, 0, 0, 200);

    /**
     * Region IDs for wave-based minigames and raids where everything is hostile.
     */
    private static final Set<Integer> MINIGAME_REGIONS = new HashSet<>(Arrays.asList(
            9551, // Fight Caves
            9043, // Inferno
            7216, // Fortis Colosseum
            9033, // Nightmare Zone (NMZ)
            7512, // The Gauntlet
            7768, // The Corrupted Gauntlet

            // ── Chambers of Xeric (CoX)
            12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145,
            13393, 13394, 13395, 13396, 13397, 13401,

            // ── Theatre of Blood (ToB)
            12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125,

            // ── Tombs of Amascut (ToA)
            14160, 14162, 14164, 14672, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700,

            // ── Pest Control
            10536, 10537,

            // ── Barbarian Assault
            7509, 7508,

            // ── Guardians of the Rift (Temple of the Eye)
            14484,

            // ── Soul Wars (Game Arena)
            8493, 8749, 9005,
            // ── Temple Trekking / Burgh de Rott Ramble
            10419));

    /** Pixels above the NPC's logical head where the label is drawn. */
    private static final int TEXT_HEIGHT_OFFSET = 40;

    private final AggroTagPlugin plugin;
    @Nonnull
    private final Client client;

    // ── Fading State ──────────────────────────────────────────────────────────
    private long lastFrameTime = 0;
    private float currentDt = 0f;
    private float globalRadiusFade = 0f; // 0.0 = bright, 1.0 = dimmed
    private final java.util.Map<Integer, Float> npcFadeMap = new java.util.HashMap<>();

    // ── Physics Bumping State ─────────────────────────────────────────────────
    private static class TagBounds {
        NPC npc;
        float centerX;
        float centerY;
        float width;
        float height;
        WorldPoint worldPoint;
    }
    private final java.util.Map<Integer, Point2D.Float> tagOffsets = new java.util.HashMap<>();
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    public AggroTagOverlay(AggroTagPlugin plugin, @Nonnull Client client, ModelOutlineRenderer modelOutlineRenderer) {

        this.plugin = plugin;
        this.client = client;
        this.modelOutlineRenderer = modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    // ── Render entry-point ────────────────────────────────────────────────────

    @Override
    public Dimension render(Graphics2D graphics) {
        if (client.getTopLevelWorldView() == null) {
            return null;
        }

        // Calculate delta time for 1-second fading
        long now = System.currentTimeMillis();
        if (lastFrameTime != 0) {
            currentDt = (now - lastFrameTime) / 1000f;
        }
        lastFrameTime = now;
        if (currentDt > 0.1f) currentDt = 0.1f; // Cap dt to prevent huge jumps from lag

        // Update global radius fade
        if (plugin.isPlayerInCombat()) {
            globalRadiusFade += currentDt;
            if (globalRadiusFade > 1f) globalRadiusFade = 1f;
        } else {
            globalRadiusFade -= currentDt;
            if (globalRadiusFade < 0f) globalRadiusFade = 0f;
        }

        // Occasional cleanup of the NPC fade map
        if (npcFadeMap.size() > 1000) {
            npcFadeMap.clear();
        }
        if (tagOffsets.size() > 1000) {
            tagOffsets.clear();
        }

        java.util.List<NPC> targetingPlayer = new java.util.ArrayList<>();
        java.util.List<NPC> otherNpcs = new java.util.ArrayList<>();
        java.util.List<NPC> aggressiveNpcs = new java.util.ArrayList<>();

        // Separate the NPCs into rendering layers and identify all aggressors
        for (NPC npc : client.getTopLevelWorldView().npcs()) {
            if (npc == null || npc.getName() == null) {
                continue;
            }

            if (plugin.isNpcExcludedByLevel(npc)) {
                continue;
            }

            if (plugin.isNpcExcludedByMaxHit(npc)) {
                continue;
            }

            if (plugin.getConfig().onlyTagSlayer() && !plugin.isSlayerTarget(npc)) {
                continue;
            }

            if (plugin.getConfig().onlyTagBosses() && !NpcAggroRadius.isBoss(npc)) {
                continue;
            }

            boolean isAggro = plugin.isAggressive(npc);
            if (isAggro) {
                // Filter out NPCs whose overlay is fully suppressed (crabs, superiors, etc.)
                if (!plugin.shouldDisableOverlay(npc)) {
                    aggressiveNpcs.add(npc);
                }
            }

            if (npc.getInteracting() == client.getLocalPlayer()) {
                targetingPlayer.add(npc);
            } else {
                otherNpcs.add(npc);
            }
        }

        // Pass 1: Unified Radius Render Pass
        // Fuses all overlapping shapes into a single uniform polygon
        if (!aggressiveNpcs.isEmpty()) {
            renderAllRadii(graphics, aggressiveNpcs);
        }

        // Physics Bumping Pass
        if (plugin.getConfig().preventTagOverlap()) {
            java.util.List<TagBounds> activeTags = new java.util.ArrayList<>();

            for (NPC npc : otherNpcs) {
                TagBounds tb = measureTag(graphics, npc, aggressiveNpcs.contains(npc));
                if (tb != null) activeTags.add(tb);
            }
            for (NPC npc : targetingPlayer) {
                TagBounds tb = measureTag(graphics, npc, aggressiveNpcs.contains(npc));
                if (tb != null) activeTags.add(tb);
            }

            for (int i = 0; i < activeTags.size(); i++) {
                TagBounds tb1 = activeTags.get(i);
                Point2D.Float off1 = tagOffsets.computeIfAbsent(tb1.npc.getIndex(), k -> new Point2D.Float(0, 0));

                for (int j = i + 1; j < activeTags.size(); j++) {
                    TagBounds tb2 = activeTags.get(j);
                    Point2D.Float off2 = tagOffsets.computeIfAbsent(tb2.npc.getIndex(), k -> new Point2D.Float(0, 0));

                    boolean sameTile = tb1.worldPoint != null && tb2.worldPoint != null && tb1.worldPoint.equals(tb2.worldPoint);

                    float c1x = tb1.centerX + off1.x;
                    float c1y = tb1.centerY + off1.y;
                    float c2x = tb2.centerX + off2.x;
                    float c2y = tb2.centerY + off2.y;

                    float dx = c1x - c2x;
                    float dy = c1y - c2y;

                    float margin = 0f; 
                    float minDistX = ((tb1.width + tb2.width) / 2f + margin) * 0.80f;
                    float minDistY = ((tb1.height + tb2.height) / 2f + margin) * 0.85f;

                    if (sameTile) {
                        // Stack vertically
                        if (Math.abs(dy) < minDistY) {
                            float pushY = (minDistY - Math.abs(dy)) * 0.10f; 
                            if (dy >= 0) { off1.y += pushY; off2.y -= pushY; }
                            else { off1.y -= pushY; off2.y += pushY; }
                        }
                    } else {
                        // Repulse smoothly proportional to penetration depth
                        if (Math.abs(dx) < minDistX && Math.abs(dy) < minDistY) {
                            if (dx == 0 && dy == 0) { dx = 0.1f; dy = 0.1f; }

                            float penX = minDistX - Math.abs(dx);
                            float penY = minDistY - Math.abs(dy);

                            // Ratio goes from 0 (barely touching) to 1 (perfectly centered on each other)
                            float overlapRatio = Math.min(penX / minDistX, penY / minDistY);
                            float dist = (float) Math.sqrt(dx*dx + dy*dy);

                            // Smooth force instead of constant 2.0 to prevent bang-bang vibration
                            float force = overlapRatio * 8.0f; 

                            float pushX = (dx / dist) * force;
                            float pushY = (dy / dist) * force * 1.5f; 

                            off1.x += pushX;
                            off1.y += pushY;
                            off2.x -= pushX;
                            off2.y -= pushY;
                        }
                    }
                }

                // Spring back to origin (limits maximum displacement and gently pulls them back when not crowded)
                off1.x *= 0.85f;
                off1.y *= 0.85f;
            }
        } else {
            // Decay all offsets quickly if disabled
            for (Point2D.Float off : tagOffsets.values()) {
                off.x *= 0.8f;
                off.y *= 0.8f;
            }
        }

        // Pass 2: Render standard NPCs on the bottom layer
        for (NPC npc : otherNpcs) {
            renderNpcLogic(graphics, npc, aggressiveNpcs.contains(npc));
        }

        // Pass 3: Render active attackers on the top layer
        for (NPC npc : targetingPlayer) {
            renderNpcLogic(graphics, npc, aggressiveNpcs.contains(npc));
        }

        return null;
    }

    // ── Unified Master Radius Generator ────────────────────────────────────────

    private void renderAllRadii(Graphics2D graphics, java.util.List<NPC> aggressiveNpcs) {
        if (plugin.getConfig().disableAggroRadius()) {
            return;
        }

        boolean colorByAttackStyle = plugin.getConfig().radiusColorByAttackStyle();
        Color defaultRadiusColor = plugin.getConfig().radiusColor();
        java.util.Map<Color, java.awt.geom.Area> colorAreas = new java.util.HashMap<>();

        boolean anyRadiusToDraw = false;

        for (NPC npc : aggressiveNpcs) {
            boolean showRadius = plugin.isRadiusHotkeyHeld() || (plugin.getConfig().hoverRadius() && isHovering(npc));
            if (!showRadius)
                continue;

            int radius = plugin.getAggroRadius(npc);
            // Skip passive or overlay-disabled NPCs
            if (radius <= 0)
                continue;

            Color npcRadiusColor = defaultRadiusColor;
            if (colorByAttackStyle) {
                int style = plugin.getAttackStyleBitmask(npc);
                if ((style & NpcDataLoader.STYLE_MAGIC) != 0) {
                    npcRadiusColor = COLOR_MAGIC;
                } else if ((style & NpcDataLoader.STYLE_RANGED) != 0) {
                    npcRadiusColor = COLOR_RANGED;
                } else if ((style & NpcDataLoader.STYLE_MELEE) != 0) {
                    npcRadiusColor = COLOR_MELEE;
                }
            }

            java.awt.geom.Area masterArea = colorAreas.computeIfAbsent(npcRadiusColor, k -> new java.awt.geom.Area());

            NPCComposition comp = npc.getTransformedComposition();
            if (comp == null)
                comp = npc.getComposition();
            int size = comp != null ? comp.getSize() : 1;

            boolean useTrueTile = plugin.getConfig().radiusTrueTile();
            WorldPoint npcLocation = plugin.getStableLocation(npc); // Debounced anchor
            var worldView = client.getTopLevelWorldView();
            LocalPoint actualLocal = npc.getLocalLocation();
            LocalPoint swLocal = null;

            if (npcLocation != null && worldView != null) {
                swLocal = LocalPoint.fromWorld(worldView, npcLocation);
            }

            int TILE = Perspective.LOCAL_TILE_SIZE;
            int sizeOffset = (size - 1) * (TILE / 2);
            int smoothOffsetX = (useTrueTile || actualLocal == null || swLocal == null) ? 0 : actualLocal.getX() - (swLocal.getX() + sizeOffset);
            int smoothOffsetY = (useTrueTile || actualLocal == null || swLocal == null) ? 0 : actualLocal.getY() - (swLocal.getY() + sizeOffset);

            if (plugin.getConfig().highlightSouthwestTile() && swLocal != null) {
                LocalPoint drawSwPoint = new LocalPoint(swLocal.getX() + smoothOffsetX, swLocal.getY() + smoothOffsetY, worldView);
                Polygon swPoly = Perspective.getCanvasTilePoly(client, drawSwPoint);
                if (swPoly != null) {
                    Color c = plugin.getConfig().southwestTileColor();
                    graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 50));
                    graphics.fill(swPoly);
                    graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 255));
                    graphics.setStroke(new BasicStroke(1.5f));
                    graphics.draw(swPoly);
                }
            }

            if (plugin.getConfig().radiusLineOfSight()) {
                if (npcLocation != null && swLocal != null && worldView != null) {
                    AggroTagPlugin.LosCache cache = plugin.getLosTiles(npc, npcLocation, radius, size);

                    java.awt.geom.Area pure2DGrid = new java.awt.geom.Area();
                    for (int i = 0; i < cache.count; i++) {
                        int packed = cache.packedOffsets[i];
                        int dx = packed >> 16;
                        int dy = (short) (packed & 0xFFFF);
                        pure2DGrid.add(new java.awt.geom.Area(new java.awt.Rectangle(dx, dy, 1, 1)));
                    }

                    java.awt.geom.GeneralPath screenPath = new java.awt.geom.GeneralPath();
                    java.awt.geom.PathIterator it = pure2DGrid.getPathIterator(null);
                    float[] coords = new float[6];
                    boolean hasMoveTo = false;

                    while (!it.isDone()) {
                        int type = it.currentSegment(coords);
                        if (type == java.awt.geom.PathIterator.SEG_CLOSE) {
                            if (hasMoveTo) {
                                screenPath.closePath();
                            }
                            hasMoveTo = false;
                        } else {
                            int localDx = (int) (coords[0] * TILE);
                            int localDy = (int) (coords[1] * TILE);

                            int px = swLocal.getX() + localDx - (TILE / 2) + smoothOffsetX;
                            int py = swLocal.getY() + localDy - (TILE / 2) + smoothOffsetY;

                            LocalPoint cornerLp = new LocalPoint(px, py, worldView);
                            Point canvasPt = Perspective.localToCanvas(client, cornerLp,
                                    worldView.getPlane());

                            if (canvasPt != null) {
                                if (type == java.awt.geom.PathIterator.SEG_MOVETO || !hasMoveTo) {
                                    screenPath.moveTo(canvasPt.getX(), canvasPt.getY());
                                    hasMoveTo = true;
                                } else if (type == java.awt.geom.PathIterator.SEG_LINETO) {
                                    screenPath.lineTo(canvasPt.getX(), canvasPt.getY());
                                }
                            } else {
                                hasMoveTo = false;
                            }
                        }
                        it.next();
                    }

                    masterArea.add(new java.awt.geom.Area(screenPath));
                    anyRadiusToDraw = true;
                }
            } else {
                // Non-LOS mode: draw a simple square polygon
                int totalSize = size + 2 * radius;
                LocalPoint drawPoint = null;

                if (swLocal != null) {
                    LocalPoint centerLp = new LocalPoint(
                            swLocal.getX() + sizeOffset,
                            swLocal.getY() + sizeOffset,
                            worldView);

                    drawPoint = new LocalPoint(
                            centerLp.getX() + smoothOffsetX,
                            centerLp.getY() + smoothOffsetY,
                            worldView);
                }

                if (drawPoint != null) {
                    Polygon tilePoly = Perspective.getCanvasTileAreaPoly(client, drawPoint, totalSize);
                    if (tilePoly != null) {
                        masterArea.add(new java.awt.geom.Area(tilePoly));
                        anyRadiusToDraw = true;
                    }
                }
            }
        }

        if (anyRadiusToDraw) {
            int opacity = plugin.getConfig().radiusOpacity();
            // Dim the radius to near-invisible when the player is in combat, fading over 1 sec
            if (plugin.getConfig().dimRadiusInCombat()) {
                int dimOp = plugin.getConfig().dimmedRadiusOpacity();
                opacity = (int) (opacity + (dimOp - opacity) * globalRadiusFade);
            }
            int radiusAlpha = (int) ((opacity / 100.0f) * 255);
            int borderAlpha = Math.min(255, (int) (radiusAlpha * 3.5));

            for (java.util.Map.Entry<Color, java.awt.geom.Area> entry : colorAreas.entrySet()) {
                Color tagColor = entry.getKey();
                java.awt.geom.Area masterArea = entry.getValue();

                Color fillColor = new Color(tagColor.getRed(), tagColor.getGreen(), tagColor.getBlue(), radiusAlpha);
                Color borderColor = new Color(tagColor.getRed(), tagColor.getGreen(), tagColor.getBlue(), borderAlpha);

                graphics.setColor(fillColor);
                graphics.fill(masterArea);
                graphics.setColor(borderColor);
                graphics.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                graphics.draw(masterArea);
            }
        }
    }

    // ── Tag Measuring ─────────────────────────────────────────────────────────

    private TagBounds measureTag(Graphics2D graphics, NPC npc, boolean isAggro) {
        boolean isTargetingPlayer = npc.getInteracting() == client.getLocalPlayer();
        boolean hiddenByConfig = (isTargetingPlayer && plugin.getConfig().hideTargeting())
                || (!isTargetingPlayer && plugin.getConfig().hideAggro());

        int regionId = -1;
        if (client.getLocalPlayer() != null && client.getLocalPlayer().getWorldLocation() != null) {
            regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        }
        boolean inMinigame = MINIGAME_REGIONS.contains(regionId);
        MinigameBehavior behavior = plugin.getConfig().minigameBehavior();

        if (inMinigame && behavior == MinigameBehavior.DISABLE_ENTIRELY) {
            return null;
        }

        boolean isCombatState = isAggro || isTargetingPlayer;
        boolean showName = isCombatState && !hiddenByConfig && !(inMinigame && behavior == MinigameBehavior.HIDE_NAMES);

        int maxHit = plugin.getMaxHit(npc);
        boolean showMaxHit = shouldShowMaxHit(isAggro, isTargetingPlayer, maxHit);

        boolean hasIdStr = (plugin.getConfig().showNpcLevel() && npc.getCombatLevel() > 0) || plugin.getConfig().showNpcId();

        if (!showName && !showMaxHit && (!isCombatState || !hasIdStr) && !plugin.getConfig().alwaysShowNpcId()) {
            return null; // nothing to render
        }

        String name = sanitizeNpcName(npc.getName());
        Point textPoint = npc.getCanvasTextLocation(graphics, name, npc.getLogicalHeight() + TEXT_HEIGHT_OFFSET);
        if (textPoint == null) {
            return null;
        }

        FontMetrics fm = graphics.getFontMetrics();
        int nameWidth = fm.stringWidth(name);

        String prefixStr = "";
        if (plugin.getConfig().showNpcLevel() && npc.getCombatLevel() > 0) {
            prefixStr += "[Lvl: " + npc.getCombatLevel() + "] ";
        }
        if (plugin.getConfig().showNpcId()) {
            prefixStr += "[" + npc.getId() + "] ";
        }
        int idWidth = prefixStr.isEmpty() ? 0 : fm.stringWidth(prefixStr);
        int height = fm.getHeight();

        int totalWidth = 0;
        boolean centerLabel = !showName;
        int npcCenterX = textPoint.getX() + nameWidth / 2 + plugin.getConfig().tagHorizontalOffset();

        if (showName) {
            if (plugin.getConfig().useSquareMarker()) {
                int sSize = plugin.getConfig().squareSize();
                totalWidth = idWidth + sSize;
                height = Math.max(height, sSize);
            } else {
                totalWidth = idWidth + nameWidth;
            }
        } else if (isCombatState) {
            totalWidth = idWidth;
        }

        if (showMaxHit) {
            int hpPercent = getHpPercent(maxHit);
            String maxHitStr = "[" + maxHit + (hpPercent >= 0 ? " \u00b7 " + hpPercent + "%" : "") + "]";
            int maxHitWidth = fm.stringWidth(maxHitStr);
            if (plugin.getConfig().colorHpNumber() || plugin.getConfig().colorHpPercent()) {
                maxHitWidth += 10; // rough approximation for size increase
                height += 4;
            }
            if (centerLabel) {
                totalWidth = idWidth + maxHitWidth;
            } else {
                totalWidth += maxHitWidth + 2; 
            }
        } else if (!isAggro && plugin.getConfig().alwaysShowNpcId()) {
            String idStr = "[" + npc.getId() + "]";
            totalWidth = fm.stringWidth(idStr);
        }

        TagBounds tb = new TagBounds();
        tb.npc = npc;
        tb.width = totalWidth;
        tb.height = height;
        tb.worldPoint = npc.getWorldLocation();

        tb.centerX = npcCenterX;
        tb.centerY = textPoint.getY() - height / 2f + plugin.getConfig().tagVerticalOffset();

        return tb;
    }

    // ── Per-NPC rendering ─────────────────────────────────────────────────────

    private void renderNpcLogic(Graphics2D graphics, NPC npc, boolean isAggro) {
        AggroTagConfig config = plugin.getConfig();
        Point2D.Float off = tagOffsets.getOrDefault(npc.getIndex(), new Point2D.Float(0, 0));

        boolean isTargetingPlayer = npc.getInteracting() == client.getLocalPlayer();
        boolean hasMaxHit = shouldShowMaxHit(isAggro, isTargetingPlayer, plugin.getMaxHit(npc));

        if (isAggro || hasMaxHit) {
            renderAggroTag(graphics, npc, isAggro, off.x, off.y);
        } else if (config.alwaysShowNpcId()) {
            renderOnlyNpcId(graphics, npc, off.x, off.y);
        }
    }

    private void renderAggroTag(Graphics2D graphics, NPC npc, boolean isAggro, float offsetX, float offsetY) {
        // ── Opacity & Single-combat dimming ────────────────────────────────────────
        // Apply base opacity from config. If this NPC cannot currently attack the
        // player (combat slot occupied in a single-combat zone), transition to the
        // dimmed opacity over 1 second so the player's active target stays visually dominant.
        final Composite savedComposite = graphics.getComposite();
        final boolean shouldBeDimmed = plugin.isDimmedByMultiCombat(npc);

        float currentFade = npcFadeMap.getOrDefault(npc.getIndex(), 0f);
        if (shouldBeDimmed) {
            currentFade += currentDt;
            if (currentFade > 1f) currentFade = 1f;
        } else {
            currentFade -= currentDt;
            if (currentFade < 0f) currentFade = 0f;
        }

        if (currentFade == 0f || currentFade == 1f) {
            if (npcFadeMap.containsKey(npc.getIndex()) && currentFade == 0f) {
                npcFadeMap.remove(npc.getIndex());
            } else if (currentFade == 1f) {
                npcFadeMap.put(npc.getIndex(), currentFade);
            }
        } else {
            npcFadeMap.put(npc.getIndex(), currentFade);
        }

        float baseAlpha = Math.max(0f, Math.min(1f, plugin.getConfig().baseOpacity() / 100f));
        float dimAlpha = Math.max(0f, Math.min(1f, plugin.getConfig().dimmedOpacity() / 100f));
        float alpha = baseAlpha + (dimAlpha - baseAlpha) * currentFade;

        if (alpha < 1f) {
            graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
        }

        // ── Hide Aggro / Hide Targeting ────────────────────────────────────────────
        // These flags only suppress the name/square marker — max hit overlays still
        // render.
        boolean isTargetingPlayer = npc.getInteracting() == client.getLocalPlayer();
        boolean hiddenByConfig = (isTargetingPlayer && plugin.getConfig().hideTargeting())
                || (!isTargetingPlayer && plugin.getConfig().hideAggro());

        String name = sanitizeNpcName(npc.getName());

        Point textPoint = npc.getCanvasTextLocation(
                graphics, name, npc.getLogicalHeight() + TEXT_HEIGHT_OFFSET);
        if (textPoint == null) {
            graphics.setComposite(savedComposite);
            return;
        }

        FontMetrics fm = graphics.getFontMetrics();
        int nameWidth = fm.stringWidth(name);

        String idStr = "";
        int idWidth = 0;
        if (plugin.getConfig().showNpcLevel() && npc.getCombatLevel() > 0) {
            idStr += "[Lvl: " + npc.getCombatLevel() + "] ";
        }
        if (plugin.getConfig().showNpcId()) {
            idStr += "[" + npc.getId() + "] ";
        }
        if (!idStr.isEmpty()) {
            idWidth = fm.stringWidth(idStr);
        }

        int shiftedTextX = textPoint.getX() + (int) offsetX;
        int shiftedTextY = textPoint.getY() + (int) offsetY;

        int y = shiftedTextY + plugin.getConfig().tagVerticalOffset();

        // ── Minigame Behavior Check ───────────────────────────────────────────────
        int regionId = -1;
        if (client.getLocalPlayer() != null
                && client.getLocalPlayer().getWorldLocation() != null) {
            regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
        }

        boolean inMinigame = MINIGAME_REGIONS.contains(regionId);
        MinigameBehavior behavior = plugin.getConfig().minigameBehavior();

        if (inMinigame && behavior == MinigameBehavior.DISABLE_ENTIRELY) {
            graphics.setComposite(savedComposite);
            return;
        }

        boolean isCombatState = isAggro || isTargetingPlayer;
        boolean showName = isCombatState && !hiddenByConfig && !(inMinigame && behavior == MinigameBehavior.HIDE_NAMES);

        // ── Name or Square rendering ──────────────────────────────────────────────
        // NOTE: shiftedTextX = npcScreenCenterX - nameWidth/2.
        // The API already positions the name centered over the NPC, so we draw
        // the name at shiftedTextX directly. NPC ID goes to the left, max hit
        // appends to the right.
        int npcCenterX = shiftedTextX + nameWidth / 2 + plugin.getConfig().tagHorizontalOffset();
        boolean useSquare = plugin.getConfig().useSquareMarker();
        boolean useOutline = (isTargetingPlayer && plugin.getConfig().npcOutlineTargeting()) || (!isTargetingPlayer && plugin.getConfig().npcOutlineAggressive());
        int squareWidth = 0; // Keep track for max hit offset

        if (isCombatState && useOutline) {
            Color outlineColor = isTargetingPlayer ? plugin.getConfig().npcOutlineTargetingYouColor()
                    : plugin.getConfig().npcOutlineAggroColor();

            float outlineAlphaMult = plugin.getConfig().npcOutlineOpacity() / 100f;
            float finalAlpha = (outlineColor.getAlpha() / 255f) * alpha * outlineAlphaMult;
            outlineColor = new Color(outlineColor.getRed(), outlineColor.getGreen(), outlineColor.getBlue(), Math.min(255, Math.max(0, (int) (finalAlpha * 255))));

            modelOutlineRenderer.drawOutline(npc, plugin.getConfig().npcOutlineWidth(), outlineColor, plugin.getConfig().npcOutlineFeather());
        }

        if (showName) {
            if (useSquare) {
                int sSize = plugin.getConfig().squareSize();
                int outline = plugin.getConfig().squareOutlineSize();
                Color fillColor = isTargetingPlayer ? plugin.getConfig().squareMarkerTargetColor()
                        : plugin.getConfig().squareMarkerColor();
                Color outlineColor = plugin.getConfig().squareOutlineColor();
                squareWidth = sSize;

                // Center the square (+ optional ID) over the NPC
                int totalWidth = idWidth + sSize;
                int startX = npcCenterX - totalWidth / 2;

                if (!idStr.isEmpty()) {
                    drawTextWithShadow(graphics, idStr, startX, y, Color.WHITE);
                }

                int sqX = startX + idWidth;
                // Offset y slightly so the square is centered on the text line
                int sqY = y - sSize + (sSize / 4);

                // Draw Outline
                if (outline > 0) {
                    graphics.setColor(outlineColor);
                    graphics.fillRect(sqX - outline, sqY - outline, sSize + (outline * 2), sSize + (outline * 2));
                }

                // Draw Inner Square
                graphics.setColor(fillColor);
                graphics.fillRect(sqX, sqY, sSize, sSize);
            } else {
                // Name is the centered anchor; ID goes to the left of it
                int nameStartX = shiftedTextX + plugin.getConfig().tagHorizontalOffset();

                if (!idStr.isEmpty()) {
                    drawTextWithShadow(graphics, idStr, nameStartX - idWidth, y, Color.WHITE);
                }

                Color nameColor = isTargetingPlayer
                        ? plugin.getConfig().targetingNameColor()
                        : plugin.getConfig().aggroNameColor();
                drawTextWithShadow(graphics, name, nameStartX, y, nameColor);
            }
        }

        // ── Calculate Max Hit State & ID string placement for Hidden Names ─────────
        int maxHit = plugin.getMaxHit(npc);
        boolean showMaxHit = shouldShowMaxHit(isAggro, isTargetingPlayer, maxHit);

        int labelX = 0;
        boolean centerLabel = !showName;

        if (centerLabel) {
            int hpPercent = showMaxHit ? getHpPercent(maxHit) : -1;
            int labelWidth = showMaxHit ? fm.stringWidth("[" + maxHit + (hpPercent >= 0 ? " \u00b7 " + hpPercent + "%" : "") + "]") : 0;

            int combinedWidth = idWidth + labelWidth;
            int startX = npcCenterX - combinedWidth / 2;

            if (!idStr.isEmpty() && isCombatState) {
                drawTextWithShadow(graphics, idStr, startX, y, Color.WHITE);
                labelX = startX + idWidth;
            } else {
                labelX = startX;
            }
        }

        // ── Max hit (skip entirely if disabled or data unavailable) ────────────────
        // Track the rightmost X position for slayer warning icon placement
        int warningX = npcCenterX + (showName ? nameWidth / 2 : 0) + plugin.getConfig().tagHorizontalOffset();

        if (!showMaxHit) {
            // No max hit to draw — slayer warnings still render
            renderSlayerWarnings(graphics, npc, warningX + 4, y, savedComposite);
            graphics.setComposite(savedComposite);
            return;
        }

        int hpPercent = getHpPercent(maxHit);

        if (!centerLabel) {
            if (useSquare) {
                // Append to the right of the centered square + ID block
                int totalWidth = idWidth + squareWidth;
                labelX = npcCenterX + totalWidth / 2 + 2;
            } else {
                // Append to the right of the name
                labelX = shiftedTextX + nameWidth + plugin.getConfig().tagHorizontalOffset();
            }
        }

        // Determine if a threshold color override is active
        boolean useThresholdColor = false;
        Color thresholdColor = null;
        int rawHpPercent = 0;
        if (plugin.getConfig().colorHpNumber()) {
            int hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
            rawHpPercent = hp > 0 ? (maxHit * 100) / hp : 0;
            // Null means no threshold was reached, so the configured Max Hit
            // Color (or attack-style coloring) stays in charge.
            thresholdColor = getThresholdColor(rawHpPercent);
            useThresholdColor = thresholdColor != null;
        }

        int maxHitEndX = labelX; // Track end of max hit for warning placement

        if (useThresholdColor) {
            // Threshold reached — use threshold color + size increase for the entire label
            Font savedFont = graphics.getFont();
            boolean fontChanged = false;
            int sizeInc = plugin.getConfig().hpPercentSizeIncrease();
            int t1 = plugin.getConfig().hpPercentThreshold1();
            int t2 = plugin.getConfig().hpPercentThreshold2();
            if (t1 >= t2) {
                if (rawHpPercent >= t1)
                    sizeInc += plugin.getConfig().hpPercentSizeIncrease50();
                else if (rawHpPercent >= t2)
                    sizeInc += plugin.getConfig().hpPercentSizeIncrease100();
            } else {
                if (rawHpPercent >= t2)
                    sizeInc += plugin.getConfig().hpPercentSizeIncrease100();
                else if (rawHpPercent >= t1)
                    sizeInc += plugin.getConfig().hpPercentSizeIncrease50();
            }
            if (sizeInc > 0) {
                graphics.setFont(savedFont.deriveFont(savedFont.getSize2D() + sizeInc));
                fontChanged = true;
            }

            FontMetrics fmScaled = graphics.getFontMetrics();
            String prefix = centerLabel ? "[" + maxHit : " [" + maxHit;
            drawTextWithShadow(graphics, prefix, labelX, y, thresholdColor);
            int curX = labelX + fmScaled.stringWidth(prefix);

            if (hpPercent >= 0) {
                curX = drawPercentageSuffix(graphics, fmScaled, curX, y, hpPercent);
            }

            drawTextWithShadow(graphics, "]", curX, y, thresholdColor);
            maxHitEndX = curX + fmScaled.stringWidth("]");

            if (fontChanged) {
                graphics.setFont(savedFont);
            }
        } else if (plugin.getConfig().colorByAttackStyle()) {
            maxHitEndX = renderStyleColoredHit(graphics, fm, npc, maxHit, hpPercent, labelX, y, centerLabel);
        } else {
            Color baseColor = plugin.getConfig().maxHitBaseColor();
            String prefix = centerLabel ? "[" + maxHit : " [" + maxHit;
            drawTextWithShadow(graphics, prefix, labelX, y, baseColor);
            int curX = labelX + fm.stringWidth(prefix);

            if (hpPercent >= 0) {
                curX = drawPercentageSuffix(graphics, fm, curX, y, hpPercent);
            }

            drawTextWithShadow(graphics, "]", curX, y, baseColor);
            maxHitEndX = curX + fm.stringWidth("]");
        }

        // ── Slayer Warning Icons (appended to the far right) ─────────────────────
        renderSlayerWarnings(graphics, npc, maxHitEndX + 4, y, savedComposite);

        // Always restore the composite regardless of which path was taken above
        graphics.setComposite(savedComposite);
    }

    /**
     * Renders one colored {@code [N]} per attack-style bit, then appends the
     * HP-percentage suffix once in grey. Falls back to yellow when style is
     * unknown.
     *
     * @return the X coordinate after the last drawn element
     */
    private int renderStyleColoredHit(
            Graphics2D graphics, FontMetrics fm,
            NPC npc, int maxHit, int hpPercent,
            int startX, int y, boolean centerLabel) {
        int style = plugin.getAttackStyleBitmask(npc);
        String numLabel = centerLabel ? "[" + maxHit + "]" : " [" + maxHit + "]";
        int numW = fm.stringWidth(numLabel);
        int curX = startX;
        boolean drew = false;

        if ((style & NpcDataLoader.STYLE_MELEE) != 0) {
            drawTextWithShadow(graphics, numLabel, curX, y, COLOR_MELEE);
            curX += numW;
            drew = true;
        }
        if ((style & NpcDataLoader.STYLE_MAGIC) != 0) {
            drawTextWithShadow(graphics, numLabel, curX, y, COLOR_MAGIC);
            curX += numW;
            drew = true;
        }
        if ((style & NpcDataLoader.STYLE_RANGED) != 0) {
            drawTextWithShadow(graphics, numLabel, curX, y, COLOR_RANGED);
            curX += numW;
            drew = true;
        }

        if (!drew) {
            // Unknown style — there is no style colour to use, so fall back to
            // the configured Max Hit Color.
            Color unknownColor = plugin.getConfig().maxHitBaseColor();
            String prefix = centerLabel ? "[" + maxHit : " [" + maxHit;
            drawTextWithShadow(graphics, prefix, curX, y, unknownColor);
            int tempX = curX + fm.stringWidth(prefix);
            if (hpPercent >= 0) {
                tempX = drawPercentageSuffix(graphics, fm, tempX, y, hpPercent);
            }
            drawTextWithShadow(graphics, "]", tempX, y, unknownColor);
            return tempX + fm.stringWidth("]");
        }

        // Single percentage appended after all colored labels
        if (hpPercent >= 0) {
            curX = drawPercentageSuffix(graphics, fm, curX, y, hpPercent);
        }
        return curX;
    }

    // ── Slayer Warning Rendering ──────────────────────────────────────────────

    /** Size of each slayer warning item icon in pixels. */
    private static final int SLAYER_ICON_SIZE = 20;
    /** The cancel sign is 1.5× the icon size. */
    private static final float CANCEL_SCALE = 1.5f;
    /** Cancel sign opacity (60%). */
    private static final float CANCEL_OPACITY = 0.6f;
    /** Cancel sign color — red. */
    private static final Color CANCEL_COLOR = new Color(255, 30, 30);
    /** Cancel sign stroke — thin (2px). */
    private static final BasicStroke CANCEL_STROKE = new BasicStroke(2f);

    /**
     * Draws slayer warning icons (item sprites with a red cancel sign) to the
     * right of the NPC tag. Each missing piece of equipment gets its own icon.
     *
     * The cancel sign is a circle with a diagonal slash, drawn at 60% opacity
     * and 1.5× the icon size so the player can still see the item underneath.
     *
     * @param graphics       the active Graphics2D context
     * @param npc            the NPC being rendered
     * @param startX         the X coordinate to start drawing icons
     * @param baselineY      the text baseline Y coordinate (icons are vertically centered)
     * @param savedComposite the original composite to restore after drawing
     */
    private void renderSlayerWarnings(Graphics2D graphics, NPC npc, int startX, int baselineY, Composite savedComposite) {
        java.util.List<Integer> missingItems = plugin.getMissingSlayerItems(npc);
        if (missingItems.isEmpty()) {
            return;
        }

        int curX = startX;
        // Center the icon vertically on the text baseline
        int iconY = baselineY - SLAYER_ICON_SIZE + 2;

        for (int itemId : missingItems) {
            // Fetch the item sprite (natively transparent, TYPE_INT_ARGB)
            BufferedImage itemImage = plugin.getItemManager().getImage(itemId);
            if (itemImage == null) {
                continue;
            }

            // Draw the scaled item icon
            graphics.drawImage(itemImage, curX, iconY, SLAYER_ICON_SIZE, SLAYER_ICON_SIZE, null);

            // Draw the cancel sign over the icon
            int cancelSize = (int) (SLAYER_ICON_SIZE * CANCEL_SCALE);
            int cancelX = curX + (SLAYER_ICON_SIZE - cancelSize) / 2;
            int cancelY = iconY + (SLAYER_ICON_SIZE - cancelSize) / 2;

            // Save state and apply cancel sign opacity
            Composite beforeCancel = graphics.getComposite();
            Stroke beforeStroke = graphics.getStroke();
            Object beforeAA = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);

            graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, CANCEL_OPACITY));
            graphics.setColor(CANCEL_COLOR);
            graphics.setStroke(CANCEL_STROKE);
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            // Circle
            graphics.drawOval(cancelX, cancelY, cancelSize, cancelSize);
            // Diagonal slash (from bottom-left to top-right, like a proper 🚫)
            int slashPad = (int) (cancelSize * 0.15);
            graphics.drawLine(
                    cancelX + slashPad, cancelY + cancelSize - slashPad,
                    cancelX + cancelSize - slashPad, cancelY + slashPad
            );

            // Restore graphics state
            graphics.setComposite(beforeCancel);
            graphics.setStroke(beforeStroke);
            if (beforeAA != null) {
                graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, beforeAA);
            }

            curX += SLAYER_ICON_SIZE + 3; // 3px gap between icons
        }
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    /**
     * Returns true when the max hit label should be drawn for this NPC — the
     * per-state toggles allow it and the bundled wiki data actually has a
     * value. NPCs outside the configured max hit window never reach here; they
     * are dropped from the render loop entirely.
     */
    private boolean shouldShowMaxHit(boolean isAggro, boolean isTargetingPlayer, int maxHit) {
        AggroTagConfig config = plugin.getConfig();
        boolean allowedByState = config.showAllMaxHits()
                || (isTargetingPlayer ? config.showTargetingMaxHit() : (isAggro && config.showAggroMaxHit()));
        return allowedByState && maxHit >= 0;
    }

    /**
     * Returns the threshold color for the given hpPercent value, or
     * {@code null} when neither threshold has been reached.
     */
    private Color getThresholdColor(int hpPercent) {
        int t1 = plugin.getConfig().hpPercentThreshold1();
        int t2 = plugin.getConfig().hpPercentThreshold2();

        if (t1 >= t2) {
            if (hpPercent >= t1) {
                return plugin.getConfig().colorHpPercent50();
            } else if (hpPercent >= t2) {
                return plugin.getConfig().colorHpPercent100();
            }
        } else {
            if (hpPercent >= t2) {
                return plugin.getConfig().colorHpPercent100();
            } else if (hpPercent >= t1) {
                return plugin.getConfig().colorHpPercent50();
            }
        }
        return null;
    }

    private boolean isHovering(NPC npc) {
        Shape hull = npc.getConvexHull();
        if (hull != null) {
            Point mouse = client.getMouseCanvasPosition();
            if (mouse != null) {
                return hull.contains(mouse.getX(), mouse.getY());
            }
        }
        return false;
    }

    /**
     * Returns {@code " · N%"} when the HP-percent config is on and the player's
     * current HP is known. Returns an empty string otherwise.
     */
    private int getHpPercent(int maxHit) {
        if (!plugin.getConfig().showHpPercent()) {
            return -1;
        }
        int hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
        if (hp <= 0) {
            return -1;
        }
        return (maxHit * 100) / hp;
    }

    private int drawPercentageSuffix(Graphics2D graphics, FontMetrics baseFm, int curX, int y, int hpPercent) {
        // Draw the separator dot
        String dot = " \u00b7 ";
        drawTextWithShadow(graphics, dot, curX, y, COLOR_PCT);
        curX += baseFm.stringWidth(dot);

        // Determine color
        Color pctColor = COLOR_PCT;
        if (plugin.getConfig().colorHpPercent()) {
            int t1 = plugin.getConfig().hpPercentThreshold1();
            int t2 = plugin.getConfig().hpPercentThreshold2();

            if (t1 >= t2) {
                if (hpPercent >= t1) {
                    pctColor = plugin.getConfig().colorHpPercent50();
                } else if (hpPercent >= t2) {
                    pctColor = plugin.getConfig().colorHpPercent100();
                }
            } else {
                if (hpPercent >= t2) {
                    pctColor = plugin.getConfig().colorHpPercent100();
                } else if (hpPercent >= t1) {
                    pctColor = plugin.getConfig().colorHpPercent50();
                }
            }
        }

        // Determine font size — base size increase always applies
        Font oldFont = graphics.getFont();
        boolean changedFont = false;
        {
            int sizeInc = plugin.getConfig().hpPercentSizeIncrease();

            // Threshold-based size increases apply when either custom color mode is on
            if (plugin.getConfig().colorHpPercent() || plugin.getConfig().colorHpNumber()) {
                int t1 = plugin.getConfig().hpPercentThreshold1();
                int t2 = plugin.getConfig().hpPercentThreshold2();

                if (t1 >= t2) {
                    if (hpPercent >= t1) {
                        sizeInc += plugin.getConfig().hpPercentSizeIncrease50();
                    } else if (hpPercent >= t2) {
                        sizeInc += plugin.getConfig().hpPercentSizeIncrease100();
                    }
                } else {
                    if (hpPercent >= t2) {
                        sizeInc += plugin.getConfig().hpPercentSizeIncrease100();
                    } else if (hpPercent >= t1) {
                        sizeInc += plugin.getConfig().hpPercentSizeIncrease50();
                    }
                }
            }

            if (sizeInc > 0) {
                graphics.setFont(oldFont.deriveFont(oldFont.getSize2D() + sizeInc));
                changedFont = true;
            }
        }

        String pctStr = hpPercent + "%";
        drawTextWithShadow(graphics, pctStr, curX, y, pctColor);
        curX += graphics.getFontMetrics().stringWidth(pctStr);

        if (changedFont) {
            graphics.setFont(oldFont);
        }

        return curX;
    }

    private void renderOnlyNpcId(Graphics2D graphics, NPC npc, float offsetX, float offsetY) {
        String idStr = "";
        if (plugin.getConfig().showNpcLevel() && npc.getCombatLevel() > 0) {
            idStr += "[Lvl: " + npc.getCombatLevel() + "] ";
        }
        idStr += "[" + npc.getId() + "]";

        // Use the same height as a name tag would be
        Point textPoint = npc.getCanvasTextLocation(graphics, idStr, npc.getLogicalHeight() + TEXT_HEIGHT_OFFSET);
        if (textPoint == null) {
            return;
        }

        FontMetrics fm = graphics.getFontMetrics();
        int x = textPoint.getX() - fm.stringWidth(idStr) / 2 + plugin.getConfig().tagHorizontalOffset() + (int) offsetX;
        int y = textPoint.getY() + plugin.getConfig().tagVerticalOffset() + (int) offsetY;

        // White text, consistent with the tagged NPC ID color
        drawTextWithShadow(graphics, idStr, x, y, Color.WHITE);
    }

    /**
     * Draws text with a 1-pixel drop shadow for readability over any background.
     */
    private void drawTextWithShadow(Graphics2D graphics, String text, int x, int y, Color color) {
        graphics.setColor(COLOR_SHADOW);
        graphics.drawString(text, x + 1, y + 1);
        graphics.setColor(color);
        graphics.drawString(text, x, y);
    }

    static String sanitizeNpcName(String name) {
        return Text.removeTags(name);
    }
}

