    public boolean isNpcExcludedByLevel(NPC npc) {
        return npc != null && isCombatLevelExcluded(
                npc.getCombatLevel(),
                config.excludeNpcsAboveLevel(),
                config.excludeNpcsBelowLevel());
    }

    static boolean isCombatLevelExcluded(int combatLevel, int excludeAboveLevel, int excludeBelowLevel) {
        return (excludeAboveLevel > 0 && combatLevel > excludeAboveLevel)
                || (excludeBelowLevel > 0 && combatLevel < excludeBelowLevel);
    }

    /**
     * Returns true when the NPC's max hit falls outside the configured window and
     * the NPC should be dropped from the overlay entirely — no tag, marker,
     * outline, radius or max hit — exactly like the combat level filter above.
     *
     * <p>An NPC missing from the bundled dataset reports a max hit of
     * {@link NpcDataLoader#UNKNOWN} (-1) and so is excluded by any lower bound,
     * mirroring how the level filter treats NPCs without a combat level.</p>
     */
    public boolean isNpcExcludedByMaxHit(NPC npc) {
        return npc != null && isMaxHitExcluded(
                getMaxHit(npc),
                config.excludeNpcsAboveMaxHit(),
                config.excludeNpcsBelowMaxHit());
    }

    static boolean isMaxHitExcluded(int maxHit, int excludeAboveMaxHit, int excludeBelowMaxHit) {
        return (excludeAboveMaxHit > 0 && maxHit > excludeAboveMaxHit)
                || (excludeBelowMaxHit > 0 && maxHit < excludeBelowMaxHit);
    }

    private int lastCombatCheckCycle = -1;
    private boolean lastCombatResult = false;

    private boolean monkeyMadness2Complete = false;

    /**
     * Returns true if the local player is currently in combat
     * (interacting with an NPC, or an NPC is interacting with the player).
     * The result is cached per game cycle to improve performance when called
     * multiple times per frame by the overlay.
     */
    public boolean isPlayerInCombat() {
        if (client.getLocalPlayer() == null) {
            return false;
        }

        int currentCycle = client.getGameCycle();
        if (currentCycle == lastCombatCheckCycle) {
            return lastCombatResult;
        }

        lastCombatCheckCycle = currentCycle;
        lastCombatResult = false;

        Actor target = client.getLocalPlayer().getInteracting();
        if (target instanceof NPC && ((NPC) target).getCombatLevel() > 0) {
            lastCombatResult = true;
            return true;
        }
        if (client.getTopLevelWorldView() != null) {
            for (NPC npc : client.getTopLevelWorldView().npcs()) {
                if (npc.getCombatLevel() > 0 && npc.getInteracting() == client.getLocalPlayer()) {
                    lastCombatResult = true;
                    return true;
                }
            }
        }
        return false;
    }

