            33340, 33449, 33445, 33447, // Newer variants
            19647, 26677, 19649, 25183, // Red slayer helmet
            11864, 26674, 11865, 25177, // Base slayer helmet + (i)
            21888, 26679, 21890, 25187, // KBD slayer helmet
